#!/usr/bin/env node
// CI/deploy guard: detect a stale packages/daemon-standalone/vendor/mcp-server.
//
// packages/daemon-standalone ships a vendored copy of packages/mcp-server's
// build output under vendor/mcp-server, generated by:
//   npm run build -w packages/mcp-server
//   npm run bundle:vendor -w packages/daemon-standalone
//
// The vendored MCP server is a runtime artifact: the standalone package exposes
// adhdev-mcp from vendor/mcp-server/index.js and the daemon points coordinators
// at that entry. Keep the committed vendor output in sync with the source build.
//
// Sourcemap note: .map files are EXCLUDED from the drift comparison. Their
// `mappings` VLQ stream is a runtime-irrelevant debug artifact whose byte layout
// varies with the esbuild/tsup toolchain version, so a vendor re-sync on a
// different node can regenerate a byte-different .map while the .js is identical.
// That is not a source drift — a real source change always shows up in the emitted
// .js — so comparing .map files only produces cross-machine false positives.

import { execFileSync } from 'node:child_process';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { vendorBuildChainFor } from './vendor-build-chain.mjs';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
// Every TRACKED vendor directory under packages/daemon-standalone/vendor. This guard
// used to diff only vendor/mcp-server, leaving the committed session-host-daemon copy
// unverified even though the same bundle:vendor run regenerates it from the same dists
// and it carries identical drift risk. The sibling root guard already checks all three
// of its copies; this keeps both layers symmetric.
const VENDOR_PATHS = [
  'packages/daemon-standalone/vendor/mcp-server',
  'packages/daemon-standalone/vendor/session-host-daemon',
];
const isWin = process.platform === 'win32';
const npm = isWin ? 'npm.cmd' : 'npm';

function run(cmd, args) {
  console.log(`$ ${cmd} ${args.join(' ')}`);
  // Node 24 on Windows refuses to spawn .cmd/.bat shims (npm.cmd) via execFile
  // without a shell — it throws `spawnSync npm.cmd EINVAL`. Run npm through the
  // shell on win32 only; POSIX behavior is unchanged. Args here are fixed and
  // space-free, so shell word-splitting is not a concern.
  execFileSync(cmd, args, { stdio: 'inherit', cwd: root, shell: isWin });
}

// Rebuild the packages that feed the vendored bundles, in dependency order.
// Shared with the root gate and the pre-commit hook via vendor-build-chain.mjs —
// this list used to be hand-maintained per script and had already drifted: it
// omitted daemon-core, which mcp-server INLINES, so this gate re-bundled whatever
// daemon-core dist happened to be on disk and could report "in sync" against bytes
// that did not match daemon-core's source.
for (const spec of vendorBuildChainFor('oss')) {
  run(npm, ['run', 'build', '-w', spec]);
}
run(npm, ['run', 'bundle:vendor', '-w', 'packages/daemon-standalone']);

// ★Compare against HEAD, not the index. A bare `git diff` is worktree-vs-index, which
// this guard can never fail on: the bundle:vendor run above just rewrote the worktree,
// and anything already `git add`ed matches the index by definition. A vendor copy that
// was COMMITTED stale therefore diffed clean and the gate went green — the failure mode
// this guard exists to catch. `diff HEAD` compares the committed bytes instead.
const stalePaths = [];
for (const vendorPath of VENDOR_PATHS) {
  try {
    // Exclude *.map: sourcemaps are a non-reproducible debug artifact (see note above).
    execFileSync(
      'git',
      ['diff', '--exit-code', '--ignore-cr-at-eol', 'HEAD', '--', vendorPath, `:(exclude,glob)${vendorPath}/**/*.map`],
      { stdio: 'inherit', cwd: root },
    );
  } catch {
    stalePaths.push(vendorPath);
  }
}

if (stalePaths.length > 0) {
  console.error(
    `\n✗ ${stalePaths.length} vendored copy/copies are stale:\n` +
    stalePaths.map((p) => `    ${p}\n`).join('') +
    `  The corresponding source package(s) changed but the vendored copy was not re-synced.\n` +
    `  Fix (from the cloud monorepo root): npm run bundle:vendor:all\n` +
    `       — re-syncs BOTH the daemon-cloud and daemon-standalone vendor copies.\n` +
    `  Standalone-only (inside oss): npm run bundle:vendor -w packages/daemon-standalone\n` +
    `  then commit the updated path(s) above.\n`,
  );
  process.exit(1);
}

console.log(`\n✓ All ${VENDOR_PATHS.length} vendored copies are in sync with their source build output:`);
for (const vendorPath of VENDOR_PATHS) console.log(`    ${vendorPath}`);
